public class Comparison {
    static class OrderService {
        private final PayService pay;

        OrderService(PayService pay) {
            this.pay = pay;
        }

        String pay(long money) {
            return "paid:" + pay.doPay(money);
        }
    }

    interface PayService {
        String doPay(long money);
    }

    static class WeChatPay implements PayService {
        public String doPay(long money) {
            return "wechat-" + money;
        }
    }

    public static void main(String[] args) {
        PayService pay = new WeChatPay();
        OrderService order = new OrderService(pay);
        System.out.println(order.pay(100));
    }
}
